"""Shared loading and statistics for the main-run analysis (pre-registered in EXPERIMENTS.md).

Every number the analysis reports is computed from the files in a run directory:
record.json, layout.json, events.jsonl, metrics.jsonl and state.jsonl.gz.
"""
from __future__ import annotations

import gzip
import json
import os
import statistics
from functools import cached_property
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
RESULTS = Path(os.environ.get("DL_RESULTS", REPO / "experiments" / "results"))
OUTPUT = REPO / "experiments" / "analysis" / "output"

AI = ["full", "no_talk", "no_memory", "frozen_hornets", "labels_good_bad"]
SCRIPTED = ["rule_bees", "random_bees"]
CONDITIONS = AI + SCRIPTED
# The main runs: every condition was launched at one commit (9cb4e7a) in one batch, so they share a stamp.
MAIN_STAMP = os.environ.get("DL_MAIN_STAMP", "20261106T101558Z")
PAIRED_SEEDS = [0, 1, 2]
# Categorical slots 1 to 7 of the dataviz reference palette, in fixed order (validated for colour vision deficiency).
COLORS = dict(zip(CONDITIONS, ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300", "#6250d6"]))
SEASONS = ["spring", "summer", "autumn", "winter"]


class Run:
    """One seed directory of one condition."""

    def __init__(self, path: Path):
        self.path = path
        self.condition = path.parent.parent.name
        self.seed = int(path.name.split("-")[1])

    @property
    def name(self) -> str:
        return str(self.path.relative_to(RESULTS))

    @cached_property
    def record(self) -> dict:
        return json.loads((self.path / "record.json").read_text())

    @cached_property
    def layout(self) -> dict:
        return json.loads((self.path / "layout.json").read_text())

    @cached_property
    def events(self) -> list[dict]:
        with open(self.path / "events.jsonl", encoding="utf-8") as f:
            return [json.loads(line) for line in f]

    @cached_property
    def metrics(self) -> list[dict]:
        with open(self.path / "metrics.jsonl", encoding="utf-8") as f:
            return [json.loads(line) for line in f]

    @cached_property
    def states(self) -> list[dict]:
        with gzip.open(self.path / "state.jsonl.gz", "rt", encoding="utf-8") as f:
            return [json.loads(line) for line in f]

    @cached_property
    def hive(self) -> set[tuple[int, int]]:
        return {(x, y) for y, row in enumerate(self.layout["rows"]) for x, c in enumerate(row) if c in "HE"}

    def of(self, kind: str) -> list[dict]:
        return [e for e in self.events if e.get("kind") == kind]

    @property
    def final(self) -> dict:
        return self.record.get("final_metrics") or {}


def runs(condition: str, stamp: str = MAIN_STAMP) -> dict[int, Run]:
    """Completed seeds (those with a record.json) of one condition's main batch, by seed."""
    base = RESULTS / condition / stamp
    out = {}
    for d in sorted(base.glob("seed-*")):
        if (d / "record.json").exists():
            r = Run(d)
            out[r.seed] = r
    return out


def describe(values: dict[int, float | None]) -> dict:
    """Mean, sd and n over the seeds that have a value; missing values are listed, never counted as zero."""
    present = {s: v for s, v in values.items() if v is not None}
    vals = list(present.values())
    return {
        "n": len(vals),
        "mean": round(statistics.fmean(vals), 4) if vals else None,
        "sd": round(statistics.stdev(vals), 4) if len(vals) > 1 else None,
        "per_seed": {str(s): (round(v, 4) if v is not None else None) for s, v in sorted(values.items())},
    }


def paired(a: dict[int, float | None], b: dict[int, float | None], seeds=PAIRED_SEEDS) -> dict:
    """Pre-registered rule: a - b is consistent when it has the same sign on every paired seed
    and the mean paired difference is larger than the sd of the paired differences."""
    diffs = {s: a[s] - b[s] for s in seeds if a.get(s) is not None and b.get(s) is not None}
    d = list(diffs.values())
    mean = statistics.fmean(d) if d else None
    sd = statistics.stdev(d) if len(d) > 1 else None
    same_sign = len(d) == len(seeds) and (all(x > 0 for x in d) or all(x < 0 for x in d))
    consistent = bool(same_sign and sd is not None and abs(mean) > sd)
    return {
        "diffs": {str(s): round(v, 4) for s, v in diffs.items()},
        "mean": round(mean, 4) if mean is not None else None,
        "sd": round(sd, 4) if sd is not None else None,
        "n": len(d),
        "same_sign": same_sign,
        "consistent": consistent,
        "verdict": ("consistently higher" if consistent and mean > 0 else
                    "consistently lower" if consistent else "no consistent difference"),
    }


def fmt(stat: dict, digits: int = 3) -> str:
    """'mean (sd x, n k)' for markdown tables."""
    if stat["mean"] is None:
        return "missing (n 0)"
    sd = f"{stat['sd']:.{digits}f}" if stat["sd"] is not None else "n/a"
    return f"{stat['mean']:.{digits}f} (sd {sd}, n {stat['n']})"

"""Per-run measures, each as pre-registered in EXPERIMENTS.md ("Pre-registration"). One function per measure.

Each function takes one Run (runs.py) and returns plain numbers or dicts; None means no data (missing).
"""
from __future__ import annotations

import math
import random
import re
from collections import Counter

from runs import SEASONS, Run

HORNET_SEASONS = ("spring", "summer", "autumn")
COORD = re.compile(r"\(\s*(\d{1,2})\s*,\s*(\d{1,2})\s*\)")  # "(27,17)", the form the perception text uses


def season_rows(run: Run) -> list[dict]:
    return sorted(run.metrics, key=lambda r: r["step"])


# ---------- E1 ----------

def deliveries_by_season(run: Run) -> list[int]:
    return [r["deliveries"] for r in season_rows(run)]


# ---------- E2 ----------

def stings_per_trip_by_year(run: Run) -> dict[int, float | None]:
    out = {}
    for year in (0, 1):
        rows = [r for r in run.metrics if r["year"] == year and r["season"] in HORNET_SEASONS]
        ended = sum(r["trips_ended"] for r in rows)
        out[year] = sum(r["stings"] for r in rows) / ended if ended else None
    return out


def sting_change(run: Run) -> float | None:
    y = stings_per_trip_by_year(run)
    return y[1] - y[0] if y[0] is not None and y[1] is not None else None


def gene_means(run: Run) -> list[dict]:
    """Hornet gene means at the end of each season with hornets."""
    return [{"year": r["year"], "season": r["season"], **{g: r[g] for g in ("smell", "hearing", "ambush")}}
            for r in season_rows(run) if r["season"] in HORNET_SEASONS and r.get("smell") is not None]


def damage_per_bee_tick_outside(run: Run) -> dict[int, float | None]:
    """Life removed by stings / bee-ticks spent outside the hive, over the seasons with hornets, per year."""
    outside = Counter()
    for st in run.states:
        if st["s"] != 3:
            outside[st["y"]] += sum(1 for b in st["b"] if (b[1], b[2]) not in run.hive)
    damage = Counter()
    for r in run.metrics:
        if r["season"] in HORNET_SEASONS:
            damage[r["year"]] += r["hornet_damage"]
    return {y: (damage[y] / outside[y] if outside[y] else None) for y in (0, 1)}


# ---------- E3 ----------

def first_spring_delivery(run: Run, year: int) -> int:
    """Ticks after the spring's start of its first delivery, censored at the season length."""
    row = next(r for r in run.metrics if r["year"] == year and r["season"] == "spring")
    return row["first_delivery"] if row["first_delivery"] is not None else run.layout["season_length"]


def spring_gain(run: Run) -> int:
    return first_spring_delivery(run, 0) - first_spring_delivery(run, 1)


def carryover(run: Run) -> dict:
    """Separates culture from individual memory: did any bee live through both springs, and had the
    first year-2 spring forager heard a coordinate near the spring bloom at home before it left?"""
    L = run.layout["season_length"]
    y2 = run.layout["season_length"] * 4
    alive_y1_spring = {b[0] for st in run.states[:L] for b in st["b"]}
    alive_y2_start = {b[0] for b in run.states[y2]["b"]} if len(run.states) > y2 else set()
    out = {"bees_alive_both_springs": sorted(alive_y1_spring & alive_y2_start), "forager": None,
           "forager_alive_y1_spring": None, "forager_heard_bloom_coord": None}
    first = next((e for e in run.of("delivery") if y2 <= e["t"] < y2 + L), None)
    if first is None:
        return out
    bee = first["bee"]
    trip = next((e for e in run.of("trip") if e["bee"] == bee and e["delivered"]
                 and e["start"] <= first["t"] <= e["start"] + e["ticks"]), None)
    left = trip["start"] if trip else first["t"]
    bloom = run.layout["bloom"]["spring"]
    heard = [e for e in run.of("say") if bee in e.get("heard_by", []) and e["t"] < left]
    near = any(max(abs(int(x) - bx), abs(int(y) - by)) <= 3
               for e in heard for x, y in COORD.findall(e["text"]) for bx, by in bloom)
    out.update(forager=bee, forager_left=left, forager_alive_y1_spring=bee in alive_y1_spring,
               forager_heard_bloom_coord=near)
    return out


# ---------- E4 ----------

def context(ctx: dict) -> str:
    m, b = ctx.get("movers", 0) > 0, ctx.get("bright", 0) > 0
    return "both" if m and b else "movers" if m else "bright" if b else "neither"


def sound_decisions(run: Run, t0: int = 0, t1: int = 10**9) -> list[tuple[str, str]]:
    return [(e["sound"], context(e.get("ctx", {}))) for e in run.of("decision")
            if e.get("sound") not in (None, "none") and t0 <= e["t"] < t1 and "ctx" in e]


def mutual_information(pairs: list[tuple[str, str]]) -> float:
    n = len(pairs)
    joint, a, b = Counter(pairs), Counter(p[0] for p in pairs), Counter(p[1] for p in pairs)
    return sum(c / n * math.log2(c * n / (a[x] * b[y])) for (x, y), c in joint.items())


def mi_test(pairs: list[tuple[str, str]], permutations: int = 1000, seed: int = 0) -> dict:
    """MI between sound and context, with a within-run permutation test on the sound labels."""
    sounds = Counter(p[0] for p in pairs)
    out = {"n_sounds": len(pairs), "by_sound": dict(sounds), "by_context": dict(Counter(pairs))}
    if len(pairs) < 2:
        return {**out, "mi": None, "note": "missing: fewer than 2 sounds"}
    mi = mutual_information(pairs)
    rng = random.Random(seed)
    labels, ctxs = [p[0] for p in pairs], [p[1] for p in pairs]
    null = []
    for _ in range(permutations):
        rng.shuffle(labels)
        null.append(mutual_information(list(zip(labels, ctxs))))
    null.sort()
    p95 = null[int(0.95 * permutations) - 1]
    return {**out, "mi": round(mi, 4), "perm_p95": round(p95, 4),
            "perm_p": round(sum(v >= mi for v in null) / permutations, 4),
            "above_p95": mi > p95,
            "note": "degenerate: one sound or one context only, so MI is 0" if len(sounds) < 2 or len(set(ctxs)) < 2 else ""}


def listener_response(run: Run) -> dict:
    """Share of flee or go_home at decisions triggered by hearing a sound, against timer decisions."""
    def share(evs):
        return {"n": len(evs), "flee_or_home": round(sum(e["intent"] in ("flee", "go_home") for e in evs) / len(evs), 4) if evs else None}
    decisions = run.of("decision")
    return {"sound": share([e for e in decisions if e["trigger"] == "sound"]),
            "timer": share([e for e in decisions if e["trigger"] == "timer"])}


# ---------- Further measures ----------

def talk_claims(run: Run) -> Counter:
    """Every coordinate pair in hive talk: near a bloom cell of the current or previous season,
    near a moving thing the speaker had in view before, or neither (unsupported)."""
    L, vision = run.layout["season_length"], run.layout["vision"]
    seen: dict[int, dict[tuple[int, int], int]] = {}
    for st in run.states:
        for b in st["b"]:
            for h in st["h"]:
                if max(abs(h[1] - b[1]), abs(h[2] - b[2])) <= vision:
                    seen.setdefault(b[0], {}).setdefault((h[1], h[2]), st["t"])
    out = Counter()
    for e in run.of("say"):
        s = (e["t"] // L) % 4
        cells = [c for name in (SEASONS[s], SEASONS[(s - 1) % 4]) for c in run.layout["bloom"].get(name, [])]
        mine = seen.get(e["bee"], {})
        for x, y in COORD.findall(e["text"]):
            x, y = int(x), int(y)
            if any(max(abs(x - bx), abs(y - by)) <= 3 for bx, by in cells):
                out["bloom"] += 1
            elif any(mine.get((x + dx, y + dy), 10**9) < e["t"] for dx in range(-3, 4) for dy in range(-3, 4)):
                out["mover"] += 1
            else:
                out["neither"] += 1
    return out


def naive_avoidance(run: Run) -> dict:
    """Each bee's first decision triggered by seeing a moving thing, before it was ever stung."""
    stung = {}
    for e in run.of("sting"):
        stung.setdefault(e["bee"], e["t"])
    first = {}
    for e in run.of("decision"):
        if e["trigger"] == "hornet" and e["bee"] not in first:
            first[e["bee"]] = e
    naive = [e for b, e in first.items() if e["t"] < stung.get(b, 10**9)]
    n = len(naive)
    return {"n": n, "flee_or_home": round(sum(e["intent"] in ("flee", "go_home") for e in naive) / n, 4) if n else None}


def mind_health(run: Run) -> dict:
    decisions = run.of("decision")
    errors = run.of("mind_error")
    fallbacks = sum(1 for e in decisions if e.get("fallback"))
    n = len(decisions)
    return {"decisions": n, "mind_errors": len(errors), "fallbacks": fallbacks,
            "fallback_share": round(fallbacks / n, 4) if n else None, "flagged": bool(n and fallbacks / n > 0.05),
            "input_tokens": sum(e.get("usage", {}).get("input_tokens", 0) for e in decisions),
            "output_tokens": sum(e.get("usage", {}).get("output_tokens", 0) for e in decisions)}

"""Compute every pre-registered measure of the main runs, from the run directories alone.

Usage:
    .venv/bin/python experiments/analysis/main_results.py

Writes experiments/analysis/output/main_results.json (every per-seed value, mean, sd, n and paired
comparison) and main_results.md (the tables EXPERIMENTS.md quotes). The pre-registration is in
EXPERIMENTS.md; the paired-consistency rule is runs.paired().
"""
from __future__ import annotations

import json
from collections import Counter

import measures as m
from runs import AI, CONDITIONS, OUTPUT, PAIRED_SEEDS, describe, fmt, paired, runs

E1_MEASURES = ["deliveries", "delivery_rate", "median_to_bloom", "stings_per_trip", "bees_mean",
               "spring_deliveries", "summer_deliveries", "autumn_deliveries",
               "spring_rate", "summer_rate", "autumn_rate"]


def collect() -> dict:
    R = {c: runs(c) for c in CONDITIONS}
    out = {"runs": {c: {s: r.name for s, r in rs.items()} for c, rs in R.items()},
           "provenance": {c: sorted({(r.record["provenance"]["git_commit"], r.record["provenance"]["git_dirty"]) for r in rs.values()})
                          for c, rs in R.items()},
           "errors": {c: {s: r.record.get("error") for s, r in rs.items() if r.record.get("error")} for c, rs in R.items()},
           "health": {c: {s: m.mind_health(r) for s, r in rs.items()} for c, rs in R.items() if c in AI}}

    def seeds(c, fn):
        return {s: fn(r) for s, r in R[c].items()}

    # E1: learning and culture
    e1 = {"by_condition": {}, "paired": {}}
    for k in E1_MEASURES:
        vals = {c: seeds(c, lambda r: r.final.get(k)) for c in CONDITIONS}
        e1["by_condition"][k] = {c: describe(v) for c, v in vals.items()}
        e1["paired"][k] = {f"full - {c}": paired(vals["full"], vals[c]) for c in ("no_talk", "no_memory", "rule_bees", "random_bees")}
    e1["deliveries_by_season"] = {c: seeds(c, m.deliveries_by_season) for c in CONDITIONS}
    out["E1"] = e1

    # E2: arms race
    change = {c: seeds(c, m.sting_change) for c in CONDITIONS}
    out["E2"] = {
        "sting_change": {c: describe(v) for c, v in change.items()},
        "stings_per_trip_y1": {c: describe(seeds(c, lambda r: m.stings_per_trip_by_year(r)[0])) for c in CONDITIONS},
        "stings_per_trip_y2": {c: describe(seeds(c, lambda r: m.stings_per_trip_by_year(r)[1])) for c in CONDITIONS},
        "paired": {"full - frozen_hornets": paired(change["full"], change["frozen_hornets"])},
        "damage_per_bee_tick_outside": {c: seeds(c, m.damage_per_bee_tick_outside) for c in CONDITIONS},
        "gene_means": {c: seeds(c, m.gene_means) for c in ("full", "frozen_hornets")},
    }

    # E3: seasonal memory
    gain = {c: seeds(c, m.spring_gain) for c in CONDITIONS}
    out["E3"] = {
        "first_delivery_y1": {c: describe(seeds(c, lambda r: m.first_spring_delivery(r, 0))) for c in CONDITIONS},
        "first_delivery_y2": {c: describe(seeds(c, lambda r: m.first_spring_delivery(r, 1))) for c in CONDITIONS},
        "gain": {c: describe(v) for c, v in gain.items()},
        "paired": {"full - no_talk": paired(gain["full"], gain["no_talk"])},
        "carryover": {c: seeds(c, m.carryover) for c in AI},
    }

    # E4: signals
    e4 = {"all": {}, "full_y1": {}, "full_y2": {}, "first_spring": {}, "listener": {}}
    for c in AI:
        e4["all"][c] = seeds(c, lambda r: m.mi_test(m.sound_decisions(r)))
        e4["listener"][c] = seeds(c, m.listener_response)
    for c in ("full", "labels_good_bad"):
        e4["first_spring"][c] = seeds(c, lambda r: m.mi_test(m.sound_decisions(r, 0, 250)))
    e4["full_y1"] = seeds("full", lambda r: m.mi_test(m.sound_decisions(r, 0, 1000)))
    e4["full_y2"] = seeds("full", lambda r: m.mi_test(m.sound_decisions(r, 1000, 2000)))
    above = sum(bool(v.get("above_p95")) for s, v in e4["all"]["full"].items() if s in PAIRED_SEEDS)
    e4["supported"] = above >= 2
    e4["full_seeds_above_p95"] = above
    out["E4"] = e4

    # Further measures
    claims = {c: seeds(c, lambda r: dict(m.talk_claims(r))) for c in AI}
    out["further"] = {
        "talk_claims": claims,
        "talk_claims_pooled": {c: dict(sum((Counter(v) for v in claims[c].values()), Counter())) for c in AI},
        "naive_avoidance": {c: seeds(c, m.naive_avoidance) for c in AI},
        "naive_avoidance_share": {c: describe(seeds(c, lambda r: m.naive_avoidance(r)["flee_or_home"])) for c in AI},
    }
    return out


def table(title: str, block: dict, conds=CONDITIONS, digits=3) -> list[str]:
    lines = [f"**{title}**", "", "| condition | mean (sd, n) | per seed |", "|---|---|---|"]
    for c in conds:
        if c in block:
            lines.append(f"| {c} | {fmt(block[c], digits)} | {block[c]['per_seed']} |")
    return lines + [""]


def pair_lines(title: str, block: dict) -> list[str]:
    lines = [f"**{title}** (paired by seed 0 to 2)", "", "| comparison | per-seed differences | mean | sd | verdict |", "|---|---|---|---|---|"]
    for name, p in block.items():
        lines.append(f"| {name} | {p['diffs']} | {p['mean']} | {p['sd']} | {p['verdict']} |")
    return lines + [""]


def markdown(r: dict) -> str:
    L = ["# Main results (generated by experiments/analysis/main_results.py; do not edit)", "",
         "Run directories:", ""] + [f"- {c}: {sorted(set(n.rsplit('/', 1)[0] for n in v.values()))}, seeds {sorted(v)}" for c, v in r["runs"].items()]
    L += ["", f"Provenance (commit, dirty): {r['provenance']}", f"Crashed seeds: {r['errors']}", "",
          "## Model health", "", "| condition | seed | decisions | mind_error | fallbacks | share | flagged | input tokens | output tokens |",
          "|---|---|---|---|---|---|---|---|---|"]
    for c, seeds in r["health"].items():
        for s, h in seeds.items():
            L.append(f"| {c} | {s} | {h['decisions']} | {h['mind_errors']} | {h['fallbacks']} | {h['fallback_share']} | {h['flagged']} | {h['input_tokens']} | {h['output_tokens']} |")
    L += ["", "## E1: learning and culture", ""]
    for k in E1_MEASURES:
        L += table(k, r["E1"]["by_condition"][k])
    L += pair_lines("E1 primary: deliveries", r["E1"]["paired"]["deliveries"])
    L += pair_lines("E1 secondary: delivery_rate", r["E1"]["paired"]["delivery_rate"])
    L += pair_lines("E1 secondary: stings_per_trip", r["E1"]["paired"]["stings_per_trip"])
    L += ["## E2: arms race", ""] + table("stings per trip, year 1", r["E2"]["stings_per_trip_y1"])
    L += table("stings per trip, year 2", r["E2"]["stings_per_trip_y2"]) + table("change, year 2 minus year 1", r["E2"]["sting_change"])
    L += pair_lines("E2 primary", r["E2"]["paired"])
    L += ["## E3: seasonal memory", ""] + table("first spring delivery, year 1 (censored at 250)", r["E3"]["first_delivery_y1"], digits=1)
    L += table("first spring delivery, year 2", r["E3"]["first_delivery_y2"], digits=1) + table("gain (year 1 minus year 2)", r["E3"]["gain"], digits=1)
    L += pair_lines("E3 primary", r["E3"]["paired"])
    L += ["**Carryover**", ""] + [f"- {c} seed {s}: {v}" for c, sv in r["E3"]["carryover"].items() for s, v in sv.items()]
    L += ["", "## E4: signals", "", f"Supported (full above its permutation 95th percentile in at least 2 of 3 seeds): {r['E4']['supported']} ({r['E4']['full_seeds_above_p95']} of 3)", "",
          "| condition | seed | sounds | by sound | MI (bits) | perm p95 | perm p | note |", "|---|---|---|---|---|---|---|---|"]
    for c, sv in r["E4"]["all"].items():
        for s, v in sv.items():
            L.append(f"| {c} | {s} | {v['n_sounds']} | {v['by_sound']} | {v['mi']} | {v.get('perm_p95')} | {v.get('perm_p')} | {v['note']} |")
    L += ["", "**Listener response** (share of flee or go_home)", ""] + [f"- {c} seed {s}: {v}" for c, sv in r["E4"]["listener"].items() for s, v in sv.items()]
    L += ["", "## Further measures", "", "**Coordinates in hive talk** (pooled over seeds)", ""] + [f"- {c}: {v}" for c, v in r["further"]["talk_claims_pooled"].items()]
    L += [""] + table("naive avoidance: share of flee or go_home at a bee's first sighting, before any sting", r["further"]["naive_avoidance_share"], AI)
    return "\n".join(L) + "\n"


def main() -> None:
    r = collect()
    OUTPUT.mkdir(parents=True, exist_ok=True)
    (OUTPUT / "main_results.json").write_text(json.dumps(r, indent=1, default=str) + "\n")
    (OUTPUT / "main_results.md").write_text(markdown(r))
    print(f"wrote {OUTPUT / 'main_results.md'}")


if __name__ == "__main__":
    main()

